('5a4e0011-0000-4000-8000-000000002387', '5a4e0010-0000-4000-8000-000000000417', '5a4e0000-0000-4000-8000-000000010111', 'Merhaba, konferans için o tarihte uygunum. Standart paketim ve ekleri için teklifi birazdan gönderiyorum; sorularınız olursa buradayım.', 'text', NULL, pg_temp.t(1511.26), pg_temp.t(1489.70)),
('5a4e0011-0000-4000-8000-000000002388', '5a4e0010-0000-4000-8000-000000000417', '5a4e0000-0000-4000-8000-000000040010', 'Teşekkürler. Toplam süre 5-6 saat olur. Bütçe konusunda biraz esneğiz, önemli olan deneyim.', 'text', NULL, pg_temp.t(1506.89), pg_temp.t(1484.90)),
('5a4e0011-0000-4000-8000-000000002389', '5a4e0010-0000-4000-8000-000000000417', '5a4e0000-0000-4000-8000-000000010111', 'Süper. Açık hava için ek ekipman gerekebilir, onu teklife ayrı kalem olarak ekledim. İsterseniz çıkarabiliriz.', 'text', NULL, pg_temp.t(1504.62), pg_temp.t(1482.38)),
('5a4e0011-0000-4000-8000-000000002390', '5a4e0010-0000-4000-8000-000000000417', '5a4e0000-0000-4000-8000-000000040010', 'Maalesef tarih değişti, şimdilik iptal ediyoruz.', 'text', NULL, pg_temp.t(1464.27), pg_temp.t(1441.44)),
('5a4e0011-0000-4000-8000-000000002391', '5a4e0010-0000-4000-8000-000000000418', '5a4e0000-0000-4000-8000-000000030003', 'Merhaba, İstanbul''de 15.12 tarihli doğum günü etkinliğimiz için teklif rica ediyorum. Mekan henüz kesinleşmedi ama tarih sabit.', 'text', NULL, pg_temp.t(2828.25), pg_temp.t(2805.54)),
('5a4e0011-0000-4000-8000-000000002392', '5a4e0010-0000-4000-8000-000000000418', '5a4e0000-0000-4000-8000-000000010013', 'Merhaba! Takvimde 15.12 boş görünüyor. Birkaç soru: etkinlik kaç saat sürecek, mekan açık mı kapalı mı? Ardından teklifi iletirim.', 'text', NULL, pg_temp.t(2784.07), pg_temp.t(2757.20)),
('5a4e0011-0000-4000-8000-000000002393', '5a4e0010-0000-4000-8000-000000000418', '5a4e0000-0000-4000-8000-000000030003', 'Açık hava, Kadıköy. Yağmur planı için alternatif de var. Ekibiniz kaç kişi geliyor?', 'text', NULL, pg_temp.t(2774.43), pg_temp.t(2758.02)),
('5a4e0011-0000-4000-8000-000000002394', '5a4e0010-0000-4000-8000-000000000418', '5a4e0000-0000-4000-8000-000000010013', 'Anladım, teşekkürler. Teklifi hazırladım; %30 kapora ile tarih kesinleşir, kalanı etkinlik günü. İptal koşulları teklifte yazıyor.', 'text', NULL, pg_temp.t(2769.50), pg_temp.t(2769.21)),
