('5a4e0011-0000-4000-8000-000000002396', '5a4e0010-0000-4000-8000-000000000419', '5a4e0000-0000-4000-8000-000000031007', 'Merhaba, referans üzerine yazıyorum. 19.01''de Ankara''de lansman var; o gün uygun musunuz? Bütçe aralığımızı da yazdım.', 'text', NULL, pg_temp.t(3706.16), pg_temp.t(3705.90)),
